// MONOTONIC STACK VARIANTS
// All are O(n) time by the push-once-pop-once argument

// VARIANT 1: NEXT GREATER ELEMENT (left to right, decreasing stack)
function nextGreater(nums) {
    const result = new Array(nums.length).fill(-1);
    const stack = []; // stores INDICES; values decrease top-to-bottom

    for (let i = 0; i < nums.length; i++) {
        // While stack top's value < current: current is the answer for stack top
        while (stack.length && nums[stack[stack.length-1]] < nums[i]) {
            const idx = stack.pop();
            result[idx] = nums[i]; // nums[i] is the next greater element for idx
        }
        stack.push(i);
    }
    // Remaining in stack: no next greater -> result stays -1
    return result;
}

// VARIANT 2: PREVIOUS SMALLER ELEMENT (same structure, different comparison)
function previousSmaller(nums) {
    const result = new Array(nums.length).fill(-1);
    const stack = []; // stores indices; values increase top-to-bottom (increasing stack)

    for (let i = 0; i < nums.length; i++) {
        // While stack top's value >= current: pop (current is smaller than top)
        while (stack.length && nums[stack[stack.length-1]] >= nums[i]) {
            stack.pop(); // top has no 'previous smaller' from the left at this position
        }
        // Stack top (if any) is the previous smaller for i
        result[i] = stack.length ? nums[stack[stack.length-1]] : -1;
        stack.push(i);
    }
    return result;
}

// DAILY TEMPERATURES (#739, L1-M04) — next greater (days ahead)
function dailyTemperatures(temperatures) {
    const result = new Array(temperatures.length).fill(0);
    const stack = []; // decreasing stack of indices
    for (let i = 0; i < temperatures.length; i++) {
        while (stack.length && temperatures[stack[stack.length-1]] < temperatures[i]) {
            const idx = stack.pop();
            result[idx] = i - idx; // days to wait
        }
        stack.push(i);
    }
    return result;
}

console.log(nextGreater([2,1,2,4,3]));      // [4,2,4,-1,-1]
console.log(dailyTemperatures([73,74,75,71,69,72,76,73])); // [1,1,4,2,1,1,0,0]

// LARGEST RECTANGLE IN HISTOGRAM (#84) — uses monotonic stack
function largestRectangleArea(heights) {
    const stack = []; // increasing stack of indices
    let maxArea = 0;
    heights = [...heights, 0]; // sentinel 0 to flush all bars at the end

    for (let i = 0; i < heights.length; i++) {
        while (stack.length && heights[stack[stack.length-1]] > heights[i]) {
            const h = heights[stack.pop()];
            const w = stack.length ? i - stack[stack.length-1] - 1 : i;
            maxArea = Math.max(maxArea, h * w);
        }
        stack.push(i);
    }
    return maxArea;
}
console.log(largestRectangleArea([2,1,5,6,2,3])); // 10

