// NEXT GREATER ELEMENT II (#503) — circular array
// O(n) time via array doubling + modulo
function nextGreaterElements(nums) {
    const n = nums.length;
    const result = new Array(n).fill(-1);
    const stack = []; // decreasing stack of indices (0..n-1)

    // Iterate 2n times to simulate circular array
    for (let i = 0; i < 2 * n; i++) {
        const val = nums[i % n]; // wrap around

        while (stack.length && nums[stack[stack.length-1]] < val) {
            const idx = stack.pop();
            result[idx] = val; // val is the next greater for idx
        }

        // Only push indices for the first pass (i < n)
        if (i < n) stack.push(i);
    }
    return result;
}

