// NEXT GREATER ELEMENT I (#496) — different problem, easier
// Given nums1 (subset of nums2), for each element in nums1
// find its next greater in nums2
function nextGreaterElement(nums1, nums2) {
    // Build next-greater map for nums2 using monotonic stack
    const nextGreaterMap = new Map();
    const stack = []; // decreasing values

    for (const num of nums2) {
        while (stack.length && stack[stack.length-1] < num) {
            nextGreaterMap.set(stack.pop(), num);
        }
        stack.push(num);
    }
    // Remaining in stack have no next greater: not in map -> return -1
    return nums1.map(n => nextGreaterMap.get(n) ?? -1);
}

