// SUM OF SUBARRAY MINIMUMS (#907)
// O(n) time via contribution + two monotonic stacks
function sumSubarrayMins(arr) {
    const MOD = 1e9 + 7;
    const n = arr.length;

    // left[i] = distance to previous strictly smaller element
    //           (or i+1 if none exists)
    const left = new Array(n);
    const stack1 = []; // increasing stack
    for (let i = 0; i < n; i++) {
        while (stack1.length && arr[stack1[stack1.length-1]] >= arr[i]) {
            stack1.pop();
        }
        left[i] = stack1.length ? i - stack1[stack1.length-1] : i + 1;
        stack1.push(i);
    }

    // right[i] = distance to next smaller or EQUAL element
    //            (or n-i if none exists)
    const right = new Array(n);
    const stack2 = []; // increasing stack
    for (let i = n - 1; i >= 0; i--) {
        while (stack2.length && arr[stack2[stack2.length-1]] > arr[i]) { // > not >=
            stack2.pop();
        }
        right[i] = stack2.length ? stack2[stack2.length-1] - i : n - i;
        stack2.push(i);
    }

    // Sum contributions: arr[i] * left[i] * right[i]
    let result = 0;
    for (let i = 0; i < n; i++) {
        result = (result + arr[i] * left[i] * right[i]) % MOD;
    }
    return result;
}

