// SLIDING WINDOW MAXIMUM (revisit from Module 11)
function maxSlidingWindow(nums, k) {
    const deque = []; // indices, decreasing values (front = max)
    const result = [];
    for (let i = 0; i < nums.length; i++) {
        // Pop front: expired
        if (deque.length && deque[0] < i - k + 1) deque.shift();
        // Pop back: dominated by nums[i]
        while (deque.length && nums[deque[deque.length-1]] <= nums[i]) deque.pop();
        deque.push(i);
        if (i >= k - 1) result.push(nums[deque[0]]);
    }
    return result;
}

// SLIDING WINDOW MINIMUM — flip the comparison
function minSlidingWindow(nums, k) {
    const deque = []; // indices, INCREASING values (front = min)
    const result = [];
    for (let i = 0; i < nums.length; i++) {
        if (deque.length && deque[0] < i - k + 1) deque.shift();
        // Pop back: dominated (back >= nums[i] means back is larger -> remove)
        while (deque.length && nums[deque[deque.length-1]] >= nums[i]) deque.pop();
        deque.push(i);
        if (i >= k - 1) result.push(nums[deque[0]]);
    }
    return result;
}

