// CONSTRAINED SUBARRAY SUM (#1425) — deque DP
// Max sum of subarray of length at most k
// dp[i] = max subarray sum ending at i
// dp[i] = prefix[i] - min(prefix[j]) for j in [i-k, i-1]
// Use monotonic deque of prefix sums for O(n)
function constrainedSubsetSum(nums, k) {
    const n = nums.length;
    const dp = [...nums]; // dp[i] = max sum subarray ending at i with length <= k
    const deque = [0];    // indices of dp values, decreasing

    for (let i = 1; i < n; i++) {
        // Pop expired: index too far back
        if (deque[0] < i - k) deque.shift();
        // dp[i] = nums[i] + max(0, dp[deque front])
        dp[i] = nums[i] + Math.max(0, dp[deque[0]]);
        // Pop dominated: smaller dp values from back
        while (deque.length && dp[deque[deque.length-1]] <= dp[i]) deque.pop();
        deque.push(i);
    }
    return Math.max(...dp);
}
console.log(constrainedSubsetSum([10,2,-10,5,20], 2)); // 37 (10+2+5+20)

