// ONLINE STOCK SPAN (#901)
// O(1) amortised per call
class StockSpanner {
    constructor() {
        this.stack = []; // [(price, span), ...] decreasing prices
    }

    next(price) {
        let span = 1; // today counts as 1

        // Pop all entries with price <= current price
        // Absorb their spans (they are all dominated by today's price)
        while (this.stack.length && this.stack[this.stack.length-1][0] <= price) {
            span += this.stack.pop()[1]; // add the span of the dominated entry
        }

        this.stack.push([price, span]); // push today with accumulated span
        return span;
    }
}

const spanner = new StockSpanner();
console.log(spanner.next(100)); // 1 (only day 1)
console.log(spanner.next(80));  // 1 (80 < 100, span resets)
console.log(spanner.next(60));  // 1 (60 < 80)
console.log(spanner.next(70));  // 2 (70 >= 60, absorbs day 3)
console.log(spanner.next(60));  // 1 (60 < 70)
console.log(spanner.next(75));  // 4 (75 >= 60,70,60 but < 80)
console.log(spanner.next(85));  // 6 (85 >= 75,60,70,60,80 but < 100)

